// Chatwoot signs outbound webhooks: sha256=HMAC_SHA256(secret, "<X-Chatwoot-Timestamp>.<raw body>")
// Source of truth: chatwoot/lib/webhooks/trigger.rb (cloned at chatwoot/).
const item = $input.first().json || {};
const headers = item.headers || {};
const h = (k) => headers[k] || headers[k.toLowerCase()];
const rawBody = typeof item.body === 'string' ? item.body : JSON.stringify(item.body ?? item);
const ts = String(h('x-chatwoot-timestamp') || '');
const sig = String(h('x-chatwoot-signature') || '');
const secret = ($env && $env.CHATWOOT_WEBHOOK_SECRET) || '';

const crypto = require('crypto');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${rawBody}`).digest('hex');
let sigOk = false;
if (sig && expected && sig.length === expected.length) {
  try { sigOk = crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected)); } catch (e) { sigOk = false; }
}

const now = Math.floor(Date.now() / 1000);
const tsNum = parseInt(ts, 10);
const tooOld = tsNum && Math.abs(now - tsNum) > 300; // 5-min replay window, enforced by the receiver

let payload = {};
try { payload = typeof rawBody === 'string' ? JSON.parse(rawBody) : (rawBody || {}); } catch (e) {}

const event = payload.event || '';
const isConv = event === 'conversation_updated';
const isMsg = event === 'message_created';

// identity round-trip: contact.custom_attributes.zalo_chat_id (set when the chatbot first mirrored the contact)
const sender = (((payload.conversation || {}).meta) || {}).sender || payload.sender || {};
const zalo_chat_id = ((sender.custom_attributes) || {}).zalo_chat_id || '';

// takeover signal: changed_attributes[].assignee_id = { previous_value, current_value }
let assigneePrev = null, assigneeCur = null;
if (isConv && Array.isArray(payload.changed_attributes)) {
  for (const c of payload.changed_attributes) {
    if (c && c.assignee_id) { assigneePrev = c.assignee_id.previous_value; assigneeCur = c.assignee_id.current_value; }
  }
}

// relay-to-Zalo filter: outgoing, non-private, sender is a human User (NOT AgentBot -> loop guard)
const msg = payload.message || payload;
const senderType = ((msg.sender) || {}).type || '';
const mt = msg.message_type;
const isAgentReply = isMsg && (mt === 'outgoing' || mt === 1) && msg.private !== true && senderType === 'User';

const refId = String(msg.id || payload.id || ((payload.conversation || {}).id) || event);
const event_id = crypto.createHash('sha256').update(`${refId}||${event}||${assigneeCur == null ? 'null' : assigneeCur}||${assigneePrev == null ? 'null' : assigneePrev}`).digest('hex');

return [{ json: {
  hmac_ok: sigOk && !tooOld,
  too_old: !!tooOld,
  event, isConv, isMsg, zalo_chat_id,
  assignee_cur: assigneeCur,            // non-null => recruiter took over
  assignee_prev: assigneePrev,          // release uses the previous owner
  is_takeover: isConv && assigneeCur != null,
  is_release:  isConv && assigneeCur == null && assigneePrev != null,
  is_agent_reply: isAgentReply,
  reply_text: isAgentReply ? String(msg.content || '') : '',
  event_id
}}];
